  readonly Action<byte[]> raw;readonly Action<Exception> failed;readonly object gate=new object();readonly Queue<Item> control=new Queue<Item>(),bulk=new Queue<Item>();Item screen,mouse;int queuedBytes,burst;bool screenTurn=true;volatile bool closed;readonly Thread worker;public long ScreenDrops,MoveDrops,LastWriteMs;public int PeakBytes;public bool HasPendingScreen{get{lock(gate)return screen!=null;}}
