  public void Send(byte[] bytes){if(bytes==null||bytes.Length==0||bytes.Length>2097152)throw new IOException("Geçersiz gönderim boyutu.");byte kind=bytes[0];if((kind==3&&bytes.Length!=10)||(kind==4&&bytes.Length!=3)||((kind==2||kind==5)&&bytes.Length!=1)||((kind==40||kind==42||kind==43||kind==68)&&bytes.Length!=5)||(kind==41&&bytes.Length>65541)||(kind==45&&bytes.Length>64)||((kind==60||kind==66||kind==69)&&bytes.Length>8192)||(kind==65&&bytes.Length>14))throw new IOException("Mesaj türü/boyutu geçersiz.");bool isScreen=kind==1,isMove=kind==3&&bytes.Length>1&&bytes[1]==0,isInput=kind==3||kind==4,urgent=Control(kind)||isInput;var item=new Item{Bytes=bytes,Wait=!(isScreen||isInput||kind==5||kind==43||kind==45||kind==60||kind==66||kind==68)};
   lock(gate){if(closed)throw new IOException("Bağlantı kapalı.");if(isScreen){if(screen!=null){queuedBytes-=screen.Bytes.Length;screen.Done.TrySetResult(true);screen=null;ScreenDrops++;}if(queuedBytes+bytes.Length>8323072){ScreenDrops++;return;}screen=item;queuedBytes+=bytes.Length;}else if(isMove){if(mouse!=null){queuedBytes-=mouse.Bytes.Length;mouse.Done.TrySetResult(true);mouse=null;MoveDrops++;}if(queuedBytes+bytes.Length>8384512){MoveDrops++;return;}mouse=item;queuedBytes+=bytes.Length;}else if(urgent){if(isInput&&mouse!=null){queuedBytes-=mouse.Bytes.Length;mouse.Done.TrySetResult(true);mouse=null;MoveDrops++;}if(control.Count>=256||queuedBytes+bytes.Length>8388608){var error=new IOException("Kontrol kuyruğu doldu; bağlantı kapasitesi aşıldı.");Close(error);ThreadPool.QueueUserWorkItem(o=>{try{failed(error);}catch{}});throw error;}control.Enqueue(item);queuedBytes+=bytes.Length;}else{while(!closed&&(bulk.Count>=32||queuedBytes+bytes.Length>8323072))Monitor.Wait(gate,200);if(closed)throw new IOException("Bağlantı kapalı.");bulk.Enqueue(item);queuedBytes+=bytes.Length;}
