 public sealed class BoundedWork:IDisposable {
  readonly object gate=new object();readonly Queue<byte[]> queue=new Queue<byte[]>();readonly Action<byte[]> consume;readonly Action<byte[]> overflow;readonly int cap;int bytes;bool closed;readonly Thread thread;
  public BoundedWork(Action<byte[]> action,int limit,Action<byte[]> onOverflow){consume=action;cap=limit;overflow=onOverflow;thread=new Thread(Run);thread.IsBackground=true;thread.Start();}
  public bool Enqueue(byte[] b){lock(gate){if(closed)return false;if(queue.Count>=256||bytes+b.Length>cap){closed=true;queue.Clear();bytes=0;Monitor.PulseAll(gate);ThreadPool.QueueUserWorkItem(o=>overflow(b));return false;}queue.Enqueue(b);bytes+=b.Length;Monitor.PulseAll(gate);return true;}}
  void Run(){while(true){byte[] b;lock(gate){while(!closed&&queue.Count==0)Monitor.Wait(gate);if(closed)return;b=queue.Dequeue();bytes-=b.Length;}try{consume(b);}catch{Dispose();try{overflow(b);}catch{}return;}}}
  public void Dispose(){lock(gate){closed=true;queue.Clear();bytes=0;Monitor.PulseAll(gate);}}
 }
 public static class Transport {
  sealed class Wire {public object Channel;public PrioritySender Sender;public System.Threading.Timer Heartbeat;}
