  public static void ConfigureTcp(TcpClient client){try{client.NoDelay=true;client.Client.SetSocketOption(SocketOptionLevel.Socket,SocketOptionName.KeepAlive,true);var data=new byte[12];Buffer.BlockCopy(BitConverter.GetBytes((uint)1),0,data,0,4);Buffer.BlockCopy(BitConverter.GetBytes((uint)10000),0,data,4,4);Buffer.BlockCopy(BitConverter.GetBytes((uint)2000),0,data,8,4);client.Client.IOControl(IOControlCode.KeepAliveValues,data,null);}catch(SocketException){}catch(PlatformNotSupportedException){}}
  public static void Bootstrap(object channel){var type=channel.GetType();var tcp=type.GetField("tcp",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(channel) as TcpClient;if(tcp!=null)ConfigureTcp(tcp);byte[] hello=System.Text.Encoding.ASCII.GetBytes("\u0006MRDAKTILO/2:FILES-CREDIT:QUEUE");RawSend(channel,hello);byte[] peer;try{peer=(byte[])type.GetMethod("Receive").Invoke(channel,null);}catch(TargetInvocationException e){throw e.InnerException??e;}if(System.Text.Encoding.ASCII.GetString(peer)!=System.Text.Encoding.ASCII.GetString(hello))throw new IOException("Karşı uygulamanın sürümü eski. İki uçtaki uygulamaları birlikte güncelleyin.");var wire=GetWire(channel);wire.Heartbeat=new System.Threading.Timer(o=>{try{wire.Sender.Send(new byte[]{5});}catch{}},null,3000,3000);}
