  public static void SessionEnded(Form form,bool byUser){if(form==null||Preview(form)||!form.Text.StartsWith("DaktiloClient"))return;FormState state;if(!forms.TryGetValue(form,out state))return;if(byUser){state.Stopped=true;if(state.Timer!=null)state.Timer.Stop();return;}if(state.Closing||state.Stopped||form.IsDisposed)return;if(state.Timer==null){state.Timer=new System.Windows.Forms.Timer();state.Timer.Tick+=(s,e)=>{state.Timer.Stop();if(state.Closing||state.Stopped||form.IsDisposed)return;var active=form.GetType().GetField("active",BindingFlags.Instance|BindingFlags.NonPublic);if(active!=null&&(bool)active.GetValue(form))return;SetLabel(form,"status","Bağlantı yeniden kuruluyor; yeni kod alınacak.");form.GetType().GetMethod("Start",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{true});};}state.Retry=Math.Min(5,state.Retry+1);state.Timer.Interval=Math.Min(30000,1000*(1<<state.Retry));SetLabel(form,"status","Bağlantı kesildi. "+(state.Timer.Interval/1000)+" saniye sonra yeni kodla tekrar denenecek.");state.Timer.Start();}
