  public static Image SafeImage(Stream stream){long start=stream.Position;try{if(stream.ReadByte()!=255||stream.ReadByte()!=216)throw new IOException("Ekran görüntüsü JPEG değil.");bool found=false;while(stream.Position<stream.Length){int marker;do{marker=stream.ReadByte();if(marker<0)throw new IOException("JPEG eksik.");}while(marker!=255);do{marker=stream.ReadByte();}while(marker==255);if(marker==217||marker==218)break;if(marker==0||marker==216||(marker>=208&&marker<=215))continue;int a=stream.ReadByte(),b=stream.ReadByte();if(a<0||b<0)throw new IOException("JPEG eksik.");int length=(a<<8)|b;if(length<2||stream.Position+length-2>stream.Length)throw new IOException("JPEG boyutu geçersiz.");if((marker>=192&&marker<=195)||(marker>=197&&marker<=199)||(marker>=201&&marker<=203)||(marker>=205&&marker<=207)){if(length<7)throw new IOException("JPEG başlığı geçersiz.");stream.ReadByte();int h=(stream.ReadByte()<<8)|stream.ReadByte(),w=(stream.ReadByte()<<8)|stream.ReadByte();if(w<=0||h<=0||w>4096||h>4096||(long)w*h>4194304)throw new IOException("Ekran görüntüsü çok büyük.");found=true;break;}stream.Position+=length-2;}if(!found)throw new IOException("JPEG boyut bilgisi yok.");}finally{stream.Position=start;}return Image.FromStream(stream);}
